'use strict';

var index = require('./index-OWCBTetj.js');

const cardTextCss = () => `:host{pointer-events:none}.card__text-wrapper{padding-bottom:0px}.card__text-wrapper.hasBtn{padding-bottom:16px}.card-text{line-height:1.5rem;font-size:1rem;font-weight:400;white-space:wrap;display:-webkit-box;-webkit-line-clamp:var(--card-text-line-clamp, 3);-webkit-box-orient:vertical;overflow:hidden;text-overflow:ellipsis}`;

const CardText = class {
    constructor(hostRef) {
        index.registerInstance(this, hostRef);
    }
    get el() { return index.getElement(this); }
    hasBtn;
    componentWillLoad() {
        const link = this.el.closest("ifx-card").querySelector("ifx-link");
        const button = this.el.closest("ifx-card").querySelector("ifx-button");
        if (link || button) {
            this.hasBtn = true;
        }
    }
    render() {
        return (index.h("div", { key: '71df4b6e7101818350d5da0088110f8382e2c712', class: `card__text-wrapper ${this.hasBtn ? "hasBtn" : ""}` }, index.h("div", { key: 'f1cf5fbd01b423fa0212d9ed330544b8a61a5541', class: `card-text` }, index.h("slot", { key: 'dccd668b121d8811a0cd9a2e956c4738cb3f303c' }))));
    }
};
CardText.style = cardTextCss();

exports.ifx_card_text = CardText;
